package com.example.aop;

import org.aspectj.lang.ProceedingJoinPoint;
import org.aspectj.lang.annotation.*;
import org.slf4j.Logger;
import org.slf4j.LoggerFactory;
import org.springframework.stereotype.Component;

@Aspect
@Component
public class AuditAspect {
    private static final Logger log = LoggerFactory.getLogger(AuditAspect.class);

    @Before("execution(* com.example.service.*.*(..))")
    public void logBefore() {
        log.info("Executing before advice: Method is about to run.");
    }

    @AfterReturning(pointcut = "execution(* com.example.service.*.*(..))", returning = "result")
    public void logAfterReturning(Object result) {
        log.info("Executing after-returning advice: Result = {}", result);
    }

    @AfterThrowing(pointcut = "execution(* com.example.service.*.*(..))", throwing = "ex")
    public void logAfterThrowing(Throwable ex) {
        log.error("Executing after-throwing advice: Exception = {}", ex.getMessage());
    }

    @After("execution(* com.example.service.*.*(..))")
    public void logAfter() {
        log.info("Executing after (finally) advice.");
    }

    @Around("execution(* com.example.service.*.*(..))")
    public Object measureExecutionTime(ProceedingJoinPoint pjp) throws Throwable {
        long start = System.currentTimeMillis();
        try {
            Object result = pjp.proceed();
            long duration = System.currentTimeMillis() - start;
            log.info("Around advice: Method {} executed in {}ms", pjp.getSignature().toShortString(), duration);
            return result;
        } catch (Throwable t) {
            log.error("Around advice caught exception, rethrowing...");
            throw t;
        }
    }
}
